(() => {
 function state(text){const s=String(text||'');if(/standby|another.*tab/i.test(s))return ['standby','Standby'];if(/^NEEDS ATTENTION/.test(s))return ['error','Needs attention'];if(/^SKIPPED/.test(s))return ['ready','Skipped a reply'];if(/^RECONNECTING/.test(s))return ['waiting','Reconnecting'];if(/^TYPING/.test(s))return ['thinking','Sending'];if(/OFF\s*[—-]|Stopped|Paused|Commands paused/i.test(s))return ['paused','Paused'];if(/RECOVERING|cooldown/i.test(s))return ['waiting','Recovering'];if(/error|failed|unavailable|Could not|NOT selected/i.test(s))return ['error','Needs attention'];if(/preview.*play|Playing.*locally|Sound playing locally/i.test(s))return ['ready','Local audio'];if(/SPEAKING|Playing/i.test(s))return ['speaking','On air'];if(/THINKING|Generating|transcrib|Preparing/i.test(s))return ['thinking','Thinking'];if(/LISTENING|Hearing speech/i.test(s))return ['listening','Listening'];if(/WAITING/i.test(s))return ['waiting','Waiting'];if(/finish Setup|Set up|Getting ready/i.test(s))return ['ready','Setup'];return ['ready','Ready'];}
 globalThis.TylerUIState=state;
})();
;/* setup-detect.js */
(() => {
 const visible=n=>!!(n?.isConnected&&n.getClientRects().length);
 function botName(doc){const nodes=[...doc.querySelectorAll('[data-self-persona-name],#global_header .supernav_container a[href*="/profiles/"],#global_header .supernav_container a[href*="/id/"]')].filter(visible);const names=[...new Set(nodes.map(n=>n.getAttribute('data-self-persona-name')||(n.innerText||n.textContent||'').trim()).filter(s=>s&&s.length<=80))];return names.length===1?names[0]:null;}
 function voice(doc,name){if(!name)return null;const candidates=[...doc.querySelectorAll('[data-voice-participants],[class*="VoiceChannelParticipants"],[class*="VoiceMembers"],[class*="voice_members"],[class*="VoiceChannel"],[class*="voicechannel"]')].filter(visible),matches=new Set();for(const container of candidates){const rows=[...container.querySelectorAll('[data-steamid],[data-miniprofile],[class*="VoiceMember"],[class*="voice_member"],[class*="VoiceUser"]')].filter(visible);for(const row of rows){const first=(row.innerText||row.textContent||'').split('\n').map(s=>s.trim()).find(Boolean);if(first?.toLowerCase()===name.trim().toLowerCase()&&row.querySelector('img'))matches.add(row);}}const rows=[...matches].filter(row=>![...matches].some(other=>other!==row&&row.contains(other)));return rows.length===1?rows[0]:null;}
 function scope(region,doc){for(let node=region;node&&node!==doc.body;node=node.parentElement){for(const attr of ['data-chatid','data-chat-group-id','data-channelid','data-chat-room-id']){const value=node.getAttribute?.(attr);if(value&&/^[\w:-]{1,100}$/.test(value))return attr+':'+value;}}return null;}
 globalThis.TylerSetup={visible,botName,voice,scope};
})();
