   lastSound:clean(S.lastSound,40),music:clean(S.music,120),musicBy:clean(S.musicBy,60),turns:(S.turns||[]).slice(-40).map(v=>Math.round(Number(v)||0)),streak:S.streak|0,best:S.best|0,
