    list.append(c.h('i','xp-menu-sep'));{const all=item(list,'xp-mi xp-all','All Programs','',()=>c.actions.settings()),go=c.brand('p3-go','xp-all-go');if(go){all.classList.add('xp-all-b');all.append(go);}}
